  static String text(
    BuildContext context,
    String key, [
    Map<String, Object?> params = const <String, Object?>{},
  ]) {
    final code = Localizations.localeOf(context).languageCode;
    final map = switch (code) {
      'kk' => _kk,
      'en' => _en,
      'zh' => _zh,
      _ => _ru,
    };
    var value = map[key] ?? _ru[key] ?? key;
    for (final entry in params.entries) {
      value = value.replaceAll('{${entry.key}}', '${entry.value ?? ''}');
    }
    return value;
  }

  static String subscriptionStatus(BuildContext context, String status) {
    return switch (status) {
      'active' => text(context, 'statusActive'),
      'pending' => text(context, 'statusPending'),
      'expired' => text(context, 'statusExpired'),
      'cancelled' => text(context, 'statusCancelled'),
      _ => status,
    };
  }

  static String languageName(BuildContext context, String code) {
    return switch (code) {
      'kk' => text(context, 'kazakh'),
      'en' => text(context, 'english'),
      'zh' => text(context, 'chinese'),
      _ => text(context, 'russian'),
    };
  }
}

extension AppStringsContext on BuildContext {
  String tr(
    String key, [
    Map<String, Object?> params = const <String, Object?>{},
  ]) => AppStrings.text(this, key, params);
}
